node --input-type=module - ttmp/2026/11/26/IRWB-021-A--deriving-streaming-attention-by-checked-rewrites <<'JS'
import {readFileSync,existsSync} from 'node:fs';
import {dirname,join,resolve} from 'node:path';
const root = process.argv[2];
let count=0;
for(const name of ['README.md','index.md','design-doc/01-deriving-a-block-streaming-attention-fold.md','reference/01-research-diary.md']){
 const doc=join(root,name), body=readFileSync(doc,'utf8');
 for(const match of body.matchAll(/\[[^\]
]+\]\(([^)
]+)\)/g)){
  if(!existsSync(resolve(dirname(doc),match[1])))throw new Error(match[1]);
  count++;
 }
}
console.log(count+' local Markdown links resolve');
JS
